<template>
    <div>
        <Head title="Notifications" />

        <h3 class="title text-center">Notifications</h3>
        <div class="row">
            <div v-for="group in alertGroups" :key="group.title" class="md:col-6">
                <Card :title="group.title">
                    <template v-for="example in group.examples" :key="example.id">
                        <div
                            v-if="!dismissed[example.id]"
                            class="alert d-flex align-items-start gap-2"
                            :class="[`alert-${example.color}`, { 'alert-with-icon': example.icon }]"
                        >
                            <i v-if="example.icon" class="material-icons" data-notify="icon" aria-hidden="true">notifications</i>
                            <span class="flex-grow-1">
                                <b v-if="example.label">{{ example.label }} – </b>{{ example.message }}
                            </span>
                            <button
                                v-if="example.dismissible"
                                type="button"
                                class="alert-dismiss flex-shrink-0 ms-auto"
                                aria-label="Dismiss notification"
                                @click="dismissed[example.id] = true"
                            ><span aria-hidden="true">×</span></button>
                        </div>
                    </template>
                </Card>
            </div>
        </div>

        <Card>
            <div class="places-buttons text-center">
                <h4 class="card-title">Notifications Places</h4>
                <p class="h4 mb-3">Click to view notifications</p>
                <div class="lg:col-8 md:col-10 mx-auto">
                    <div class="row">
                        <div v-for="position in positions" :key="position" class="md:col-4">
                            <button type="button" class="btn btn-primary w-100" @click="showNotification(position)">
                                {{ position.replace('-', ' ') }}
                            </button>
                        </div>
                    </div>
                </div>
            </div>

            <div class="text-center">
                <h4 class="card-title mt-2 mb-3">Modal</h4>
                <div class="d-flex flex-wrap justify-content-center gap-1">
                    <button type="button" class="btn btn-primary btn-round" @click="$refs.classic.show()">Classic modal</button>
                    <button type="button" class="btn btn-info btn-round" @click="$refs.notice.show()">Notice modal</button>
                    <button type="button" class="btn btn-rose btn-round" @click="$refs.small.show()">Small alert modal</button>
                </div>
            </div>
        </Card>

        <Modal ref="classic" title="Modal title">
            <p>
                Far far away, behind the word mountains, far from the countries Vokalia and Consonantia,
                there live the blind texts. Separated they live in Bookmarksgrove right at the coast of the
                Semantics, a large language ocean.
            </p>
            <div class="form-group">
                <label for="notification-demo-date">Date and time</label>
                <input id="notification-demo-date" type="datetime-local" class="form-control" value="2018-11-06T00:00" />
            </div>
            <template #footer>
                <button type="button" class="btn btn-link" @click="$refs.classic.hide()">Nice Button</button>
            </template>
        </Modal>

        <Modal ref="notice" title="How Do You Become an Affiliate?" dialog-class="dialog-notice" :footer-close="false">
            <div v-for="step in noticeSteps" :key="step.title" class="row align-items-start mb-3">
                <div class="md:col-8">
                    <strong>{{ step.title }}</strong>
                    <p class="description">{{ step.description }}</p>
                </div>
                <div class="md:col-4">
                    <img :src="step.image" class="rounded img-fluid" alt="" />
                </div>
            </div>
            <template #footer>
                <button type="button" class="btn btn-info btn-round mx-auto" @click="$refs.notice.hide()">Sounds good!</button>
            </template>
        </Modal>

        <Modal ref="small" title="Small alert" dialog-class="dialog-sm" :footer-close="false">
            <p>Are you sure you want to do this?</p>
            <template #footer>
                <div class="d-flex justify-content-center w-100">
                    <button type="button" class="btn btn-link" @click="$refs.small.hide()">Never mind</button>
                    <button type="button" class="btn btn-success btn-link" @click="$refs.small.hide()">Yes</button>
                </div>
            </template>
        </Modal>
    </div>
</template>

<script>
import { Head } from '@inertiajs/vue3';
import Card from '@scaffold/components/Card.vue';
import Modal from '@scaffold/components/Modal.vue';
import registerImage from '@scaffold-assets/listing-milan.jpg';
import applyImage from '@scaffold-assets/listing-barcelona.jpg';

export default {
    name: 'NotificationsDemo',
    components: { Card, Head, Modal },
    layout: { pageTitle: 'Notifications' },
    data() {
        return {
            dismissed: {},
            dismissToast: null,
            positions: ['top-left', 'top-center', 'top-right', 'bottom-left', 'bottom-center', 'bottom-right'],
            alertGroups: [
                {
                    title: 'Notifications Style',
                    examples: [
                        { id: 'plain', color: 'info', message: 'This is a plain notification.' },
                        { id: 'dismissible', color: 'info', dismissible: true, message: 'This is a notification with a close button.' },
                        { id: 'icon', color: 'info', dismissible: true, icon: true, message: 'This is a notification with close button and icon and have many lines. You can see that the icon and the close button are always vertically aligned. This is a beautiful notification. So you don’t have to worry about the style.' },
                        { id: 'rose-icon', color: 'rose', dismissible: true, icon: true, message: 'This is a notification with close button and icon and is made with ".alert-rose". You can see that the icon and the close button are always vertically aligned. This is a beautiful notification. So you don’t have to worry about the style.' },
                    ],
                },
                {
                    title: 'Notification states',
                    examples: ['info', 'success', 'warning', 'danger', 'primary', 'rose'].map((color) => ({
                        id: `state-${color}`,
                        color,
                        dismissible: true,
                        label: color,
                        message: `This is a regular notification made with .alert-${color}.`,
                    })),
                },
            ],
            noticeSteps: [
                { title: '1. Register', description: 'Create an account to get started.', image: registerImage },
                { title: '2. Apply', description: 'Submit your affiliate application.', image: applyImage },
            ],
        };
    },
    beforeUnmount() {
        this.dismissToast?.();
    },
    methods: {
        async showNotification(position) {
            const { default: alertify } = await import('alertifyjs');
            this.dismissToast?.();

            const previousPosition = alertify.get('notifier', 'position');
            alertify.set('notifier', 'position', position);

            const notification = alertify.message('Welcome to Material Dashboard.', 5, () => {
                alertify.set('notifier', 'position', previousPosition);
                this.dismissToast = null;
            });
            this.dismissToast = () => notification.dismiss();
        },
    },
};
</script>
